/**
 * Copies the economy lab's journeys (`docs/design/valley/economy/journeys/`, generated by
 * `pnpm --filter @creatures/econ report`) into the valley prototype (`src/proto/welcome/journeys/`), byte for
 * byte, so the prototype plays exactly what the lab wrote. Dev only; nothing here ships.
 *
 *   pnpm --filter @creatures/activity proto:journeys           (copy)
 *   pnpm --filter @creatures/activity proto:journeys --check   (exit 1 when a copy differs)
 *
 * A test (`src/proto/welcome/journeys.test.ts`) makes the same comparison, so a copy cannot drift.
 */
/* global console */
import { copyFileSync, mkdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const from = join(here, '../../../docs/design/valley/economy/journeys');
const to = join(here, '../src/proto/welcome/journeys');
const FILES = ['daily.json', 'weekly.json'];

const check = process.argv.includes('--check');
if (!check) mkdirSync(to, { recursive: true });
let differs = false;
for (const file of FILES) {
  if (check) {
    let same;
    try {
      same = readFileSync(join(from, file), 'utf8') === readFileSync(join(to, file), 'utf8');
    } catch {
      same = false;
    }
    if (!same) {
      differs = true;
      console.error(`${file} differs from the lab's copy (run proto:journeys)`);
    }
  } else {
    copyFileSync(join(from, file), join(to, file));
    console.log(`copied ${file}`);
  }
}
if (differs) process.exit(1);
